def specialty_occupation_defensibility(company, role):
    team = get_design_team_education_signal(company)
    posting = score_job_description_specificity(role.description)
    # rewards HCI/interaction-design; penalizes 'creative problem-solver' vagueness
    if team.formal_degree_ratio > 0.6 and posting > 0.5:
        return {'defensibility': 'high',
                'note': 'Team + posting support specialty classification'}
    if team.formal_degree_ratio < 0.3:
        return {'defensibility': 'low',
                'note': 'Largely self-taught team — RFE risk elevated'}
    return {'defensibility': 'medium',
            'note': 'Mixed signal — insufficient to confirm either way'}
